import os
from hcso_tool.mock.tool import (
    write_file,
    base64_encode,
    linux_exec,
    append_sys_path,
    linux_do,
)
import sys
import json

SCC_CONF = """
[CRYPTO]
primaryKeyStoreFile=ks/primary.ks
standbyKeyStoreFile=ks/standby.ks
backupFolderName=backup/
logCfgFile=logger.conf
logCategory=SCC
domainCount=8
logFilePath=/opt/cloud/logs/scc
logFileName=scc
;/dev/urandom 或  /dev/random
randomDevice=/dev/random
defaultAlgorithm=AES256_CBC
;defaultAlgorithm=SM4_CBC
enableChangeFilePermission=true
;信号量的key,0x20161111 - 0x20169999
semKey=0x20167878
;信号量的权限，0600 - 0660
semPermission=0600
enableHw=false
"""
KS_NAME = dict(soc="", isap="", sa="", hcc="", logstash="", pulsar="")
for k in KS_NAME:
    KS_NAME[k] = os.environ.get(f"{k}_primary")
SEC_PATH = "/usr/local/seccomponent/bin/CryptoAPI"
KS_DIR = "/tmp/scc"
ENC_JSON = dict(store_path="", decrypt=dict(), encrypt=dict())


def get_conf(c: str):
    ret = f"{KS_DIR}/{c}/scc.conf"
    write_file(f"{KS_DIR}/{c}/scc.conf", SCC_CONF, replace_flag=False)
    write_file(
        f"{KS_DIR}/{c}/ks/primary.ks", base64_encode(KS_NAME[c]), replace_flag=False
    )
    write_file(
        f"{KS_DIR}/{c}/ks/standby.ks", base64_encode(KS_NAME[c]), replace_flag=False
    )
    if not os.path.exists(ret):
        raise Exception(f"not exist->{ret}")
    return ret


def store_local_open():
    ENC_JSON.update(store_path="/tmp/enc.json")
    if os.path.exists(ENC_JSON["store_path"]):
        ENC_JSON.update(
            json.loads(open(ENC_JSON["store_path"], "r", encoding="utf-8").read())
        )
    return KS_NAME


def store_save(data, key, value):
    if not ENC_JSON["store_path"]:
        return
    data[key] = value
    with open(ENC_JSON["store_path"], "w", encoding="utf-8") as f:
        f.write(json.dumps(ENC_JSON))


def install_scc():
    _, ARCH = linux_exec("arch")
    linux_do(
        f"rpm -ivh /opt/cloud/site-packages/seccomponent-1.1.8-release.{ARCH}.rpm --nodeps --force"
    )


def scc(conf, value, en):
    conf_path = get_conf(conf)
    if not os.path.isdir("/usr/local/seccomponent/lib"):
        install_scc()
    if os.path.isdir("/usr/local/seccomponent/lib"):
        append_sys_path("/usr/local/seccomponent/lib")
        from CryptoAPI import CryptoAPI

        cry = CryptoAPI()
        try:
            cry.initialize(conf_path)
            if en == "e":
                ret = cry.encrypt(value)
            else:
                ret = cry.decrypt(value)
        except Exception as e:
            ret = None
        finally:
            cry.finalize()
        return ret
    elif os.path.exists(SEC_PATH):
        cmd = f"""echo '{value}' | {SEC_PATH} -f {conf_path} -{en}"""
        _, info = linux_exec(cmd)
        return info.strip().split("text:").pop().split("\n")[0]
    else:
        import requests

        ed = "encrypt" if en == "e" else "decrypt"
        res = requests.post(
            f'{ENC_JSON["service_url"]}/ed/decrypt_call',
            json=dict(conf=conf, value=value),
            timeout=60,
            proxies=dict(http=None, https=None),
        )
        try:
            return json.loads(res.text)["data"]["result"]
        except Exception as e:
            raise Exception(f"{res.status_code} {res.content} {e} {ed} {conf} {value}")


def decrypt(value: str):
    decrypt_len = len("$decrypt(")
    value_type = ""
    value_type1 = ""
    if value.startswith("$decrypt("):
        value = value[decrypt_len:-1]
        value_type = "$decrypt("
        value_type1 = ")"
    if value.startswith("${ENC("):
        value = value[len("${ENC(") : -1]
        value_type = "${ENC("
        value_type1 = ")}"
    if value.startswith("ENC("):
        value = value[len("ENC(") : -1]
        value_type = "ENC("
        value_type1 = ")"
    if value.startswith("AAA") or value.startswith("BBB"):
        if value in ENC_JSON["decrypt"]:
            dec_type, dec_value = ENC_JSON["decrypt"][value]
            return value_type + dec_type + value_type1, dec_value
        for name in KS_NAME.keys():
            dec_value = scc(name, value, "d")
            if dec_value is not None:
                store_save(ENC_JSON["decrypt"], value, [name, dec_value])
                return value_type + name + value_type1, dec_value
        raise Exception(f"dec fail {value}")
    return value_type + value_type1, value


def encrypt(conf, value):
    value = decrypt(value)[1]
    key = f"{conf}_{value}"
    if key in ENC_JSON["encrypt"]:
        return ENC_JSON["encrypt"][key]
    ret = scc(conf, value, "e")
    store_save(ENC_JSON["encrypt"], key, ret)
    return ret
